package Day2;

public class FoodMenu {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int choice = 2;

        switch (choice) {
            case 1:
                System.out.println("Burger");
                break;
            case 2:
                System.out.println("Pizza");
                break;
            case 3:
                System.out.println("Pasta");
                break;
            default:
                System.out.println("Invalid Choice");
        }

	}

}
